// For each value, the next greater value to its right (or -1)
function nextGreater(values: number[]): number[] {
  const result = new Array(values.length).fill(-1)
  const stack: number[] = [] // indexes still waiting for an answer
  values.forEach((v, i) => {
    while (stack.length && values[stack.at(-1)!] < v) {
      result[stack.pop()!] = v
    }
    stack.push(i)
  })
  return result
}

