# For each value, the next greater value to its right (or -1)
def next_greater(values):
    result = [-1] * len(values)
    stack = []  # indexes still waiting for an answer
    for i, v in enumerate(values):
        while stack and values[stack[-1]] < v:
            result[stack.pop()] = v
        stack.append(i)
    return result

